                float depth = fract(1.0/r + t);
                float size = 0.05 * i * r;
                float angle_seed = floor(a * (10.0 * (0.8 + u_mid * 0.5)) * i);
                if(random(vec2(angle_seed, floor(depth*(10.0 * (0.8 + u_mid * 0.5))))) > 0.95) {
                     stars += 1.0 / (abs(fract(depth*10.0) - (0.5 * (0.8 + u_mid * 0.5))) * (20.0 * (0.8 + u_mid * 0.5)));
                }
